using System;using System.IO;using System.IO.Compression;using System.Net;using System.Diagnostics;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;using System.Security.Cryptography;using System.Web.Script.Serialization;using Microsoft.Win32;using System.Collections.Generic;
class LexusUpdater : Form {
 const string Base="https://lexus.vaidya-gpt.com";static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 Label status=new Label();Button action=new Button();ProgressBar progress=new ProgressBar();bool ready=false,complete=false,busy=false,missing=false;string root,version;Dictionary<string,object> release;
 LexusUpdater(bool auto=true){Text="LEXUS Updater";ClientSize=new Size(520,250);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.White;
 Controls.Add(new Label{Text="Update LEXUS",Font=new Font("Segoe UI",20,FontStyle.Bold),Location=new Point(24,20),Size=new Size(460,40)});
 Controls.Add(new Label{Text="Finds your installed LEXUS automatically.\nDownloads and verifies the latest update.\nYour profiles and activation data are preserved.",Location=new Point(24,70),Size=new Size(470,66)});
 status.SetBounds(24,143,470,30);status.Text="Checking your installation...";Controls.Add(status);progress.SetBounds(24,177,470,16);Controls.Add(progress);action.Text="Checking...";action.Enabled=false;action.SetBounds(335,205,160,30);Controls.Add(action);InstallerTheme.Apply(this,status,action,progress);
 action.Click+=async(s,e)=>{if(complete){Close();return;}if(missing){Process.Start(Base+"/downloads");return;}if(ready)await Apply();else await Check();};if(auto)Shown+=async(s,e)=>{await Check();if(ready&&!complete)await Apply();};}
 static string Detect(){var choices=new List<string>();using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\LEXUS")){if(key!=null)choices.Add(Convert.ToString(key.GetValue("InstallLocation")));}choices.Add(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","LEXUS"));foreach(var candidate in choices){if(String.IsNullOrWhiteSpace(candidate))continue;try{var folder=Path.GetFullPath(candidate);var metadata=Path.Combine(folder,"package.json");if(!File.Exists(Path.Combine(folder,"LEXUS.exe"))||!File.Exists(metadata))continue;var p=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(metadata));if(Convert.ToString(p["name"])=="lexus")return folder;}catch{}}return null;}
 static string InstalledVersion(string directory){return Convert.ToString(Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(directory,"package.json")))["version"]);}
 static bool InstallationClosed(string directory){foreach(var p in Process.GetProcesses()){try{if(p.Id!=Process.GetCurrentProcess().Id&&p.MainModule.FileName.StartsWith(directory+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return false;}catch{}}return true;}
 static bool Verify(string file,string hash,long bytes){if(new FileInfo(file).Length!=bytes)return false;using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").Equals(hash,StringComparison.OrdinalIgnoreCase);}
 async Task Check(){action.Enabled=false;try{root=Detect();if(root==null){status.Text="LEXUS is not installed. Use the Windows Setup.";action.Text="Open setup downloads";action.Enabled=true;missing=true;return;}version=InstalledVersion(root);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var web=new WebClient()){release=Json.Deserialize<Dictionary<string,object>>(await web.DownloadStringTaskAsync(Base+"/api/portal/downloads"));}Version current,latest;if(!Version.TryParse(version,out current)||!Version.TryParse(Convert.ToString(release["version"]),out latest))throw new Exception("Invalid release version");if(latest<=current){status.Text="LEXUS "+version+" is already up to date.";action.Text="Close";complete=true;action.Enabled=true;return;}ready=true;status.Text="Found LEXUS "+version+". Latest: "+latest;action.Text="Update / Restart";action.Enabled=true;}catch(Exception error){status.Text="Could not check for updates.";action.Text="Retry";action.Enabled=true;MessageBox.Show(error.Message,"LEXUS Updater");}}
 async Task Apply(){if(busy)return;if(!InstallationClosed(root)){MessageBox.Show("Close LEXUS and its booking browser, then click Update / Restart.","LEXUS Updater");return;}busy=true;action.Enabled=false;try{var item=(Dictionary<string,object>)release["updater"];var url=new Uri(new Uri(Base),Convert.ToString(item["url"]));var hash=Convert.ToString(item["sha256"]);var bytes=Convert.ToInt64(item["bytes"]);if(url.Scheme!="https"||url.Host!="lexus.vaidya-gpt.com"||!url.AbsolutePath.StartsWith("/downloads/LEXUS-Updater-")||!url.AbsolutePath.EndsWith(".zip")||!String.IsNullOrEmpty(url.Query)||hash.Length!=64||bytes<=0||bytes>268435456)throw new Exception("Invalid update metadata");var work=Path.Combine(Path.GetTempPath(),"lexus-update-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);var archive=Path.Combine(work,"update.zip");status.Text="Downloading update...";using(var web=new WebClient()){web.DownloadProgressChanged+=(s,e)=>progress.Value=Math.Max(0,Math.Min(100,e.ProgressPercentage));await web.DownloadFileTaskAsync(url,archive);}status.Text="Verifying downloaded update...";if(!Verify(archive,hash,bytes))throw new Exception("Update verification failed");if(!InstallationClosed(root))throw new Exception("Close LEXUS before applying the update");var helper=Path.Combine(work,"apply-update.ps1");using(var zip=ZipFile.OpenRead(archive)){var entry=zip.GetEntry("app/apply-update.ps1");if(entry==null)throw new Exception("Update helper missing");entry.ExtractToFile(helper,true);}var info=new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+helper+"\" -Package \""+archive+"\" -ExpectedHash "+hash+" -InstallRoot \""+root+"\"");info.WorkingDirectory=work;info.UseShellExecute=false;info.CreateNoWindow=true;status.Text="Applying update and restarting LEXUS...";progress.Style=ProgressBarStyle.Marquee;using(var process=Process.Start(info)){await Task.Run(()=>process.WaitForExit());if(process.ExitCode!=0)throw new Exception("Update failed. See "+Path.Combine(work,"update-error.txt"));}progress.Style=ProgressBarStyle.Blocks;progress.Value=100;status.Text="LEXUS updated. Your data is preserved.";complete=true;action.Text="Close";action.Enabled=true;}catch(Exception error){progress.Style=ProgressBarStyle.Blocks;status.Text="Update failed. Your previous files are preserved.";action.Enabled=true;MessageBox.Show(error.Message,"LEXUS Updater");}finally{busy=false;}}
 [STAThread] static int Main(string[] args){if(args.Length==1&&args[0]=="/detect"){var folder=Detect();Console.WriteLine(Json.Serialize(new{found=folder!=null,path=folder,version=folder==null?null:InstalledVersion(folder)}));return folder==null?1:0;}if(args.Length==4&&args[0]=="/verify"){try{return Verify(args[1],args[2],Int64.Parse(args[3]))?0:1;}catch{return 1;}}Application.EnableVisualStyles();if(args.Length==2&&args[0]=="/preview"){using(var form=new LexusUpdater(false))InstallerTheme.Preview(form,args[1]);return 0;}Application.Run(new LexusUpdater());return 0;}
}
